def stable_unique(items):
    """
    删除重复元素但保留第一次出现的顺序。

    元素可能是整数、字符串、元组，也可能是不可哈希的嵌套列表或嵌套字典。
    字典比较按键值内容（键顺序无关）；嵌套结构按内容深比较。

    :param items: 列表
    :return: 去重后的列表
    """
    seen = set()
    result = []

    def _is_equal(a, b):
        if isinstance(a, dict) and isinstance(b, dict):
            return set(a.items()) == set(b.items())
        elif isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
            return len(a) == len(b) and all(_is_equal(x, y) for x, y in zip(a, b))
        else:
            return a == b

    for item in items:
        if not _is_equal(item, next((x for x in result if _is_equal(x, item)), None)):
            result.append(item)
            seen.add(tuple(sorted(item.items()) if isinstance(item, dict) else item))

    return result
