            record = json.loads(line)
        except json.JSONDecodeError:
            result["invalid"] += 1
            continue

        if not all(key in record for key in ["service", "latency_ms", "status"]):
            result["invalid"] += 1
            continue

        service = record["service"]
        latency_ms = record["latency_ms"]
        status = record["status"]

        if not isinstance(latency_ms, (int, float)) or not isinstance(status, (int, float)):
            result["invalid"] += 1
            continue

        if status < 200 or status >= 300:
            result["invalid"] += 1
            continue

        if service not in service_metrics:
            service_metrics[service] = {"count": 0, "ok_rate": 0.0, "p95_latency_ms": None}

        service_metrics[service]["count"] += 1
        service_metrics[service]["ok_rate"] = (service_metrics[service]["ok_rate"] * service_metrics[service]["count"] + 1) / (service_metrics[service]["count"] + 1)

        if service_metrics[service]["count"] == 1:
            service_metrics[service]["p95_latency_ms"] = latency_ms
        else:
            sorted_latency_ms = sorted([x["latency_ms"] for x in lines if x["service"] == service and x["status"] < 300])
            if sorted_latency_ms:
                service_metrics[service]["p95_latency_ms"] = sorted_latency_ms[ceil(0.95 * len(sorted_latency_ms)) - 1]

    for service, metrics in service_metrics.items():
        metrics["count"] = metrics["count"] - result["invalid"]

    for service, metrics in service_metrics.items():
        if metrics["count"] > 0:
            metrics["ok_rate"] = metrics["ok_rate"] * metrics["count"] / (metrics["count"] + result["invalid"])
        else:
            metrics["ok_rate"] = 0.0

    return {**result, **dict(sorted(service_metrics.items()))}

