class CycleError(Exception):
    """异常类，表示存在环"""
    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__(f"存在环：{cycle}")


def dependency_plan(nodes, edges):
    """
    对任务依赖图拓扑排序
    :param nodes: 节点列表
    :param edges: 边列表，(a,b) 表示 a 必须先于 b
    :return: 拓扑排序后的节点列表
    """
    # 构建图
    graph = {}
    for node in nodes:
        graph[node] = []
    for edge in edges:
        if edge[0] not in nodes:
            raise ValueError(f"输入含未知节点：{edge[0]}")
        if edge[1] not in nodes:
            raise ValueError(f"输入含未知节点：{edge[1]}")
        graph[edge[0]].append(edge[1])

    # 检查环
    visited = set()
    rec_stack = set()
    for node in nodes:
        if node not in visited:
            if has_cycle(graph, node, visited, rec_stack):
                raise CycleError(get_cycle(graph, node, visited, rec_stack))

    # 拓扑排序
    in_degree = {node: 0 for node in nodes}
    for edges in graph.values():
        for node in edges:
            in_degree[node] += 1
    queue = [node for node in nodes if in_degree[node] == 0]
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)
    if len(result) != len(nodes):
        raise ValueError("图中存在环或有多个入度为 0 的节点")

    return result


def has_cycle(graph, node, visited, rec_stack):
    """
    检查是否存在环
    :param graph: 图
    :param node: 当前节点
    :param visited: 访问过的节点
    :param rec_stack: 递归栈
    :return: 是否存在环
    """
    visited.add(node)
    rec_stack.add(node)
    for neighbor in graph[node]:
        if neighbor not in visited:
            if has_cycle(graph, neighbor, visited, rec_stack):
                return True
        elif neighbor in rec_stack:
            return True
    rec_stack.remove(node)
    return False


def get_cycle(graph, node, visited, rec_stack):
    """
    获取环
    :param graph: 图
    :param node: 当前节点
    :param visited: 访问过的节点
    :param rec_stack: 递归栈
    :return: 环
    """
    cycle = []
    while True:
        neighbor = rec_stack.pop()
        cycle.append(neighbor)
        if neighbor == node:
            break
    return cycle[::-1]


