class StreamingGroupSum:
    def __init__(self):
        self.invalid_count = 0
        self.key_order = set()
        self.key_values = {}

    def __iter__(self):
        return self

    def __next__(self):
        if not self.key_order:
            raise StopIteration
        key = self.key_order.pop()
        total = self.key_values[key]
        del self.key_values[key]
        return (key, total)

    def process(self, row):
        try:
            timestamp, key, value = row
            if not isinstance(value, (int, float)):
                self.invalid_count += 1
                return
            if key in self.key_order:
                self.key_values[key] += value
            else:
                self.key_order.add(key)
                self.key_values[key] = value
        except ValueError:
            self.invalid_count += 1


def streaming_group_sum(rows):
    g = StreamingGroupSum()
    for row in rows:
        g.process(row)
    return g


# 示例使用
