import time
import functools

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    """
    尝试多次调用函数，直到成功或达到最大尝试次数。

    Args:
        fn (callable): 需要被重试的函数。
        attempts (int): 最大尝试次数。
        retry_if (callable): 异常判断函数，返回 True 表示重试，False 表示放弃。
        base_delay (float, optional): 基础延迟时间。 Defaults to 0.01。
        sleep (callable, optional): 等待函数，用于测试。 Defaults to time.sleep.

    Raises:
        ValueError: 如果 attempts 小于 1。
        Exception: 最终失败的异常。
    """
    if attempts < 1:
        raise ValueError("attempts must be greater than 0")

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        delay = base_delay
        for attempt in range(1, attempts + 1):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                if retry_if(e):
                    sleep(delay)
                    delay *= 2
                else:
                    raise e
        raise Exception(f"最终失败的异常：{args}, {kwargs}")

    return wrapper
