import threading
from collections import defaultdict

class SingleFlightTTLCache:
    def __init__(self, ttl=60):
        self.ttl = ttl
        self.cache = {}
        self.lock = threading.Lock()
        self.locks = defaultdict(threading.Lock)
        self.results = defaultdict(threading.Condition)

    def get(self, key):
        with self.lock:
            if key in self.cache:
                value, expire = self.cache[key]
                if expire > threading.main_thread().get_ident():
                    return value
                del self.cache[key]
        return None

    def set(self, key, value):
        with self.lock:
            self.cache[key] = (value, threading.main_thread().get_ident() + self.ttl)
            self.locks[key].acquire()

    def delete(self, key):
        with self.lock:
            if key in self.cache:
                del self.cache[key]
            self.locks[key].release()

    def __len__(self):
        with self.lock:
            return len(self.cache)

    def get_or_load(self, key, loader):
        with self.lock:
            if key in self.cache:
                value, expire = self.cache[key]
                if expire > threading.main_thread().get_ident():
                    return value
                del self.cache[key]
            if self.locks[key].locked():
                with self.results[key]:
                    self.results[key].wait()
            try:
                value = loader()
                self.set(key, value)
                return value
            except Exception as e:
                self.locks[key].release()
                with self.results[key]:
                    self.results[key].notify_all()
                raise e
            finally:
                self.locks[key].release()
                with self.results[key]:
                    self.results[key].notify_all()
