import threading
from functools import wraps
from queue import Queue
from typing import Callable, Any

class IdempotentEventProcessor:
    def __init__(self):
        self._lock = threading.Lock()
        self._queue = Queue()
        self._results = {}

    def process(self, event_id: str, payload: Any, apply: Callable[[Any], Any]):
        with self._lock:
            if event_id in self._results:
                return self._results[event_id]

            self._queue.put((event_id, payload, apply))

        self._process_queue()

    def result(self, event_id: str) -> Any:
        with self._lock:
            if event_id not in self._results:
                raise KeyError(f"Event {event_id} not found")

            return self._results[event_id]

    def _process_queue(self):
        while not self._queue.empty():
            event_id, payload, apply = self._queue.get()

            try:
                result = apply(payload)
                self._results[event_id] = result
            except Exception as e:
                self._queue.put((event_id, payload, apply))

            self._queue.task_done()

def retry_on_failure(max_attempts: int = 3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempts += 1
                    if attempts == max_attempts:
                        raise
        return wrapper
    return decorator

class IdempotentEventProcessorWithRetry(IdempotentEventProcessor):
    def __init__(self):
        super().__init__()
        self._retry_lock = threading.Lock()

    def process(self, event_id: str, payload: Any, apply: Callable[[Any], Any]):
        @retry_on_failure()
        def apply_with_retry(payload: Any):
            return apply(payload)

        return super().process(event_id, payload, apply_with_retry)
```

上述代码实现了一个线程安全的 IdempotentEventProcessor，支持重试机制。它使用一个队列来存储待处理的事件，并使用锁来确保线程安全。每个事件都有一个唯一的 ID，重复调用同一个事件 ID 将只产生一次副作用，并且返回同一结果。处理失败允许后续重试，失败不会永久占用事件 ID。不同事件 ID 可并行处理。结果可以通过 `result` 方法获取，未成功事件 ID 将抛出 KeyError。

