def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers and false otherwise.
    Knowing that (a) is less then 100.
    Example: is_multiply_prime(30) == True 30 = 2 * 3 * 5 """

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def get_prime_factors(n):
        factors = []
        for i in range(2, n + 1):
            while n % i == 0:
                factors.append(i)
                n //= i
        return factors

    prime_factors = get_prime_factors(a)
    return len(prime_factors) == 3 and all(is_prime(factor) for factor in prime_factors)

